import React, { useState } from 'react';

// Type definitions
interface Template {
  id: string;
  url: string;
  name: string;
  category: 'diwali' | 'holi';
}

// Sample image URLs (using royalty‑free / placeholder friendly images)
const diwaliTemplates: Template[] = [
  {
    id: 'd1',
    url: 'data:image/jpeg;base64,',
    name: 'Diyas & Lights',
    category: 'diwali',
  },
  {
    id: 'd2',
    url: 'data:image/jpeg;base64,',
    name: 'Lantern Glow',
    category: 'diwali',
  },
  {
    id: 'd3',
    url: 'data:image/jpeg;base64,',
    name: 'Festive Sweets',
    category: 'diwali',
  },
  {
    id: 'd4',
    url: 'data:image/jpeg;base64,',
    name: 'Rangoli Art',
    category: 'diwali',
  },
  {
    id: 'd5',
    url: 'data:image/jpeg;base64,',
    name: 'Fireworks',
    category: 'diwali',
  },
];

const holiTemplates: Template[] = [
  {
    id: 'h1',
    url: 'data:image/jpeg;base64,',
    name: 'Color Splash',
    category: 'holi',
  },
  {
    id: 'h2',
    url: 'data:image/jpeg;base64,',
    name: 'Gulal Powder',
    category: 'holi',
  },
  {
    id: 'h3',
    url: 'data:image/jpeg;base64,',
    name: 'Celebration',
    category: 'holi',
  },
  {
    id: 'h4',
    url: 'data:image/jpeg;base64,',
    name: 'Holi Drums',
    category: 'holi',
  },
  {
    id: 'h5',
    url: 'data:image/jpeg;base64,',
    name: 'Water Colors',
    category: 'holi',
  },
];

const allTemplates = [...diwaliTemplates, ...holiTemplates];

const Greetings: React.FC = () => {
  // State
  const [category, setCategory] = useState<'diwali' | 'holi'>('diwali');
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>(diwaliTemplates[0].id);
  const [businessName, setBusinessName] = useState<string>('');
  const [message, setMessage] = useState<string>('Happy Diwali!');
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [removeBranding, setRemoveBranding] = useState<boolean>(false);

  // Derived: current template object
  const currentTemplate = allTemplates.find((t) => t.id === selectedTemplateId) || allTemplates[0];

  // Handlers
  const handleCategoryChange = (cat: 'diwali' | 'holi') => {
    setCategory(cat);
    // auto‑select first template of the new category
    const firstOfCat = allTemplates.find((t) => t.category === cat);
    if (firstOfCat) setSelectedTemplateId(firstOfCat.id);
  };

  const handleTemplateSelect = (id: string) => {
    setSelectedTemplateId(id);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setLogoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdatePreview = () => {
    // In a real app you might generate a canvas, but for demo we just re‑render.
    alert('Preview updated (simulated).');
  };

  const handleDownload = () => {
    // Real implementation would use canvas or backend. Here we just simulate.
    alert('Download started (demo). In a real app this would generate an image.');
  };

  // Get templates for current category
  const displayedTemplates = allTemplates.filter((t) => t.category === category);

  return (
    <div style={styles.container}>
      {/* Left Panel – Controls */}
      <div style={styles.leftPanel}>
        <h2 style={styles.heading}>Select Template</h2>

        {/* Category Tabs */}
        <div style={styles.tabContainer}>
          <button
            style={{ ...styles.tab, ...(category === 'diwali' ? styles.activeTab : {}) }}
            onClick={() => handleCategoryChange('diwali')}
          >
            Diwali
          </button>
          <button
            style={{ ...styles.tab, ...(category === 'holi' ? styles.activeTab : {}) }}
            onClick={() => handleCategoryChange('holi')}
          >
            Holi
          </button>
        </div>

        {/* Template Thumbnails */}
        <div style={styles.thumbnailGrid}>
          {displayedTemplates.map((template) => (
            <div
              key={template.id}
              style={{
                ...styles.thumbnail,
                ...(selectedTemplateId === template.id ? styles.selectedThumbnail : {}),
              }}
              onClick={() => handleTemplateSelect(template.id)}
            >
              <img src={template.url} alt={template.name} style={styles.thumbImg} />
              <span style={styles.thumbName}>{template.name}</span>
            </div>
          ))}
        </div>

        {/* Customisation Form */}
        <div style={styles.formGroup}>
          <label style={styles.label}>Your Business Name *</label>
          <input
            type="text"
            value={businessName}
            onChange={(e) => setBusinessName(e.target.value)}
            placeholder="e.g. Mahesh Nayak pvt ltd Nimrani"
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label style={styles.label}>Message to be sent with the greeting *</label>
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            rows={3}
            style={styles.textarea}
          />
        </div>

        <div style={styles.formGroup}>
          <label style={styles.label}>Your Business Logo</label>
          <input type="file" accept="image/*" onChange={handleLogoUpload} style={styles.fileInput} />
          {logoPreview && (
            <div style={styles.logoPreviewContainer}>
              <img src={logoPreview} alt="logo preview" style={styles.logoPreview} />
            </div>
          )}
        </div>

        <div style={styles.checkboxGroup}>
          <input
            type="checkbox"
            id="removeBranding"
            checked={removeBranding}
            onChange={(e) => setRemoveBranding(e.target.checked)}
          />
          <label htmlFor="removeBranding">Remove Refrens Branding</label>
        </div>

        <div style={styles.buttonGroup}>
          <button onClick={handleUpdatePreview} style={styles.primaryButton}>
            Update Preview
          </button>
          <button onClick={handleDownload} style={styles.secondaryButton}>
            Download Image
          </button>
        </div>
      </div>

      {/* Right Panel – Preview */}
      <div style={styles.rightPanel}>
        <h3 style={styles.previewHeading}>Preview</h3>
        <div style={styles.previewCard}>
          {/* Template Background */}
          <div
            style={{
              ...styles.previewImage,
              backgroundImage: `url(${currentTemplate.url})`,
            }}
          >
            {/* Overlay Content */}
            <div style={styles.overlay}>
              {businessName && <div style={styles.previewBusiness}>{businessName}</div>}
              <div style={styles.previewMessage}>{message}</div>
              {logoPreview && (
                <div style={styles.previewLogoContainer}>
                  <img src={logoPreview} alt="logo" style={styles.previewLogo} />
                </div>
              )}
            </div>
          </div>

          {/* Optional branding */}
          {!removeBranding && (
            <div style={styles.branding}>
              Proud Member of Refrens.com
            </div>
          )}
        </div>
        <p style={styles.note}>
          (In a full version, the text would be rendered onto the image.)
        </p>
      </div>
    </div>
  );
};

